import * as THREE from './vendor/three.module.js';
import {HumanoidCharacter} from './humanoid-character.js?v=prismwing-177';
export const SPECTRUM=['#ff4764','#ff983d','#ffe35b','#62ed81','#44d9ff','#5980ff','#c070ff'];
const Y=new THREE.Vector3(0,1,0);
export class PrismwingCharacter {
 constructor(root,model){this.root=root;this.character=new HumanoidCharacter(model,{variant:'prism',height:2.4});root.add(this.character.root);this.wings=[];this.feathers=[];this.tails=[];this.box=new THREE.BoxGeometry(1,1,1);this.ball=new THREE.IcosahedronGeometry(.5,1);const mat=color=>new THREE.MeshStandardMaterial({color,roughness:.56,metalness:.18});this.gold=mat('#f6d46d');this.hair=mat('#442342');this.dark=mat('#302557');this.white=mat('#f4f5e5');this.colors=SPECTRUM.map(mat);this.glow=new THREE.MeshBasicMaterial({color:'#fff0b9',toneMapped:false});this.makeArt();this.reset();}
 mesh(parent,geometry,material,position,scale=[1,1,1]){const m=new THREE.Mesh(geometry,material);m.position.set(...position);m.scale.set(...scale);m.castShadow=m.receiveShadow=true;parent.add(m);return m;}
 attach(bone,offset){const c=this.character,g=new THREE.Group();g.position.copy(c.world(bone)).add(new THREE.Vector3(...offset));this.root.add(g);this.root.updateWorldMatrix(true,true);c.nodes[bone].attach(g);return g;}
 feather(){const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute([0,0,0,-.12,.22,.025,-.14,.7,0,0,1,-.015,.14,.7,0,.12,.22,.025,0,.5,.09],3));geo.setIndex([0,1,6,1,2,6,2,3,6,3,4,6,4,5,6,5,0,6,0,5,4,0,4,3,0,3,2,0,2,1]);geo.computeVertexNormals();return geo;}
 makeArt(){const c=this.character,head=this.attach('B_Head',[0,.12,0]);this.mesh(head,this.ball,this.hair,[0,.07,-.03],[.49,.45,.43]);for(const sign of[-1,1]){this.mesh(head,this.ball,this.hair,[sign*.19,-.14,-.03],[.18,.47,.25]);this.mesh(head,this.ball,this.white,[sign*.095,-.02,.205],[.065,.052,.035]);this.mesh(head,this.ball,this.dark,[sign*.095,-.02,.225],[.032,.039,.02]);}const crest=this.featherGeometry=this.feather();for(let i=0;i<3;i++){const f=this.mesh(head,crest,this.colors[i],[.13+i*.04,.15,-.06],[.6,.45+i*.06,.6]);f.rotation.z=-.25-i*.18;}
  const chest=this.attach('B_Spine2',[0,0,0]);this.mesh(chest,this.ball,this.colors[4],[0,-.02,0],[.56,.62,.4]);this.mesh(chest,this.box,this.gold,[0,.13,.23],[.38,.065,.025]);this.mesh(chest,this.ball,this.glow,[0,.05,.245],[.1,.13,.05]);const belt=this.attach('B_Pelvis',[0,-.05,0]);this.mesh(belt,new THREE.CylinderGeometry(.25,.3,.13,10),this.gold,[0,0,0]);for(let i=0;i<7;i++){const f=this.mesh(belt,crest,this.colors[i],[(i-3)*.065,-.08,-.15],[.8,.6,.8]);f.rotation.z=Math.PI+(i-3)*.12;this.tails.push(f);}
  const back=this.attach('B_Spine2',[0,.15,-.22]);for(const sign of[-1,1]){const wing=new THREE.Group();wing.position.set(sign*.2,0,0);back.add(wing);const outer=new THREE.Group();outer.position.set(sign*1.2,.08,-.05);wing.add(outer);this.mesh(wing,this.ball,this.colors[0],[sign*.45,.04,0],[1.1,.38,.3]);this.mesh(wing,this.ball,this.colors[1],[sign*.95,.04,0],[.75,.3,.24]);for(let i=0;i<10;i++){const f=this.mesh(outer,crest,this.colors[i<3?2:i<6?3:i<8?4:5],[sign*(i*.095),.1-i*.045,.02-i*.012],[1.35,1.15+i*.035,1]);f.rotation.z=-sign*(Math.PI*.60-i*.04);this.feathers.push(f);}for(let i=0;i<7;i++){const f=this.mesh(wing,crest,this.colors[i<3?0:i<5?1:2],[sign*(.1+i*.14),-.06,.1],[1.2,.7+i*.035,1]);f.rotation.z=-sign*(Math.PI*.85-i*.05);}this.wings.push({wing,outer,sign});}
  this.wand=this.attach('B_R_Hand',[0,0,0]);this.mesh(this.wand,new THREE.CylinderGeometry(.027,.035,.8,7),this.gold,[0,.35,0]);this.mesh(this.wand,this.ball,this.dark,[0,0,0],[.085,.2,.085]);this.star=new THREE.Group();this.star.position.y=.84;this.wand.add(this.star);for(let i=0;i<7;i++){const a=i*Math.PI*2/7,f=this.mesh(this.star,new THREE.ConeGeometry(.065,.23,4),this.colors[i],[Math.sin(a)*.15,Math.cos(a)*.15,0]);f.rotation.z=-a;}this.mesh(this.star,this.ball,this.glow,[0,0,0],[.14,.14,.14]);this.tip=new THREE.Object3D();this.tip.position.y=1.03;this.wand.add(this.tip);
 }
 reset(){this.character.reset();this.flap=0;this.pose(0,0,new THREE.Vector3(),null,false);}
 pose(dt,time,velocity,target,casting){const c=this.character;c.update('Idle',dt);for(let i=0;i<c.bones.length;i++){c.bones[i].position.copy(c.rest[i].p);c.bones[i].quaternion.copy(c.rest[i].q);}const speed=velocity.length(),glide=Math.min(1,speed/16),lean=.08+glide*.18;c.nodes.B_Spine.rotation.x+=lean;c.nodes.B_Spine1.rotation.x+=lean*.3;c.nodes.B_L_Thigh.rotation.x+=.12+glide*.35;c.nodes.B_R_Thigh.rotation.x+=.05+glide*.32;c.nodes.B_L_Calf.rotation.x+=.25+Math.sin(time*2.4)*.07;c.nodes.B_R_Calf.rotation.x+=.4+Math.sin(time*2.4+1)*.08;this.root.updateWorldMatrix(true,true);
  const neutral=this.root.localToWorld(new THREE.Vector3(-.4,1.25,.3));c.arm('L',neutral);const right=target&&casting?target:this.root.localToWorld(new THREE.Vector3(.48,1.5,.36));c.arm('R',right);this.root.updateWorldMatrix(true,true);const hand=c.hand('R'),direction=casting&&target?target.clone().sub(hand).normalize():new THREE.Vector3(.2,.9,.35).transformDirection(this.root.matrixWorld);const q=new THREE.Quaternion().setFromUnitVectors(Y,direction);this.wand.quaternion.copy(this.wand.parent.getWorldQuaternion(new THREE.Quaternion()).invert()).multiply(q);
  this.flap=Math.sin(time*(glide>.7?4:7));for(const {wing,outer,sign}of this.wings){wing.rotation.y=sign*(.12+this.flap*(.22-glide*.10));wing.rotation.z=sign*(.05+this.flap*(.33-glide*.13));outer.rotation.y=sign*(.15+Math.sin(time*7-.8)*.14*(1-glide*.5));outer.rotation.z=sign*(.08+this.flap*.08);}for(let i=0;i<this.tails.length;i++)this.tails[i].rotation.x=Math.sin(time*4+i*.45)*.12;this.star.rotation.y=time*2;this.root.updateWorldMatrix(true,true);
 }
 muzzle(){return this.tip.getWorldPosition(new THREE.Vector3());}
 diagnostics(){return{...this.character.diagnostics(),wings:this.wings.length,feathers:this.feathers.length+14,flap:this.flap,wand:this.muzzle().toArray(),rightHand:this.character.hand('R').toArray()};}
}
